/* fannkuch-redux — the equivalent-semantics C peer for the tuonelang
 * fannkuch-redux workload (the Benchmarks Game's fannkuch-redux): for every
 * permutation of 0..N, count the prefix reversals ("pancake flips") until 0
 * reaches the front; report the maximum and an alternating-sign checksum.
 * The identical computation: the same permutation order (the Benchmarks
 * Game's rotation scheme), the same flip loop. For N = 10 the checksum is
 * 73196 and the maximum 38; the exit byte is (checksum + max) % 256. */
#define N 10

int main(void) {
    long long perm[N], perm1[N], count[N];
    long long max_flips = 0, checksum = 0, perm_count = 0;
    long long r = N;
    for (long long i = 0; i < N; i++) perm1[i] = i;
    for (;;) {
        while (r != 1) {
            count[r - 1] = r;
            r = r - 1;
        }
        for (long long i = 0; i < N; i++) perm[i] = perm1[i];
        long long flips = 0;
        long long k = perm[0];
        while (k != 0) {
            long long lo = 0, hi = k;
            while (lo < hi) {
                long long t = perm[lo];
                perm[lo] = perm[hi];
                perm[hi] = t;
                lo = lo + 1;
                hi = hi - 1;
            }
            flips = flips + 1;
            k = perm[0];
        }
        if (flips > max_flips) max_flips = flips;
        if (perm_count % 2 == 0) checksum = checksum + flips;
        else checksum = checksum - flips;
        for (;;) {
            if (r == N) return (int)((checksum + max_flips) % 256);
            long long perm0 = perm1[0];
            for (long long i = 0; i < r; i++) perm1[i] = perm1[i + 1];
            perm1[r] = perm0;
            count[r] = count[r] - 1;
            if (count[r] > 0) break;
            r = r + 1;
        }
        perm_count = perm_count + 1;
    }
}

// fannkuch-redux — the equivalent-semantics Go peer for the tuonelang
// fannkuch-redux workload (the Benchmarks Game's fannkuch-redux): the same
// rotation-order permutation walk and flip loop for n = 10. Checksum 73196,
// maximum 38; exit byte (73196 + 38) % 256 = 18.
package main

import "os"

func fannkuch(n int) int64 {
	perm := make([]int64, n)
	perm1 := make([]int64, n)
	count := make([]int64, n)
	var maxFlips, checksum, permCount int64
	for i := range perm1 {
		perm1[i] = int64(i)
	}
	r := n
	for {
		for r != 1 {
			count[r-1] = int64(r)
			r--
		}
		copy(perm, perm1)
		var flips int64
		k := perm[0]
		for k != 0 {
			lo, hi := int64(0), k
			for lo < hi {
				perm[lo], perm[hi] = perm[hi], perm[lo]
				lo++
				hi--
			}
			flips++
			k = perm[0]
		}
		if flips > maxFlips {
			maxFlips = flips
		}
		if permCount%2 == 0 {
			checksum += flips
		} else {
			checksum -= flips
		}
		for {
			if r == n {
				return (checksum + maxFlips) % 256
			}
			perm0 := perm1[0]
			for i := 0; i < r; i++ {
				perm1[i] = perm1[i+1]
			}
			perm1[r] = perm0
			count[r]--
			if count[r] > 0 {
				break
			}
			r++
		}
		permCount++
	}
}

func main() {
	os.Exit(int(fannkuch(10)))
}

//! fannkuch-redux — the equivalent-semantics Rust peer for the tuonelang
//! fannkuch-redux workload (the Benchmarks Game's fannkuch-redux): the same
//! rotation-order permutation walk and flip loop for n = 10. Checksum 73196,
//! maximum 38; exit byte (73196 + 38) % 256 = 18.

fn fannkuch(n: usize) -> i64 {
    let mut perm = vec![0i64; n];
    let mut perm1: Vec<i64> = (0..n as i64).collect();
    let mut count = vec![0i64; n];
    let (mut max_flips, mut checksum, mut perm_count) = (0i64, 0i64, 0i64);
    let mut r = n;
    loop {
        while r != 1 {
            count[r - 1] = r as i64;
            r -= 1;
        }
        perm.copy_from_slice(&perm1);
        let mut flips = 0i64;
        let mut k = perm[0] as usize;
        while k != 0 {
            let (mut lo, mut hi) = (0usize, k);
            while lo < hi {
                perm.swap(lo, hi);
                lo += 1;
                hi -= 1;
            }
            flips += 1;
            k = perm[0] as usize;
        }
        if flips > max_flips {
            max_flips = flips;
        }
        if perm_count % 2 == 0 {
            checksum += flips;
        } else {
            checksum -= flips;
        }
        loop {
            if r == n {
                return (checksum + max_flips) % 256;
            }
            let perm0 = perm1[0];
            for i in 0..r {
                perm1[i] = perm1[i + 1];
            }
            perm1[r] = perm0;
            count[r] -= 1;
            if count[r] > 0 {
                break;
            }
            r += 1;
        }
        perm_count += 1;
    }
}

fn main() {
    std::process::exit(fannkuch(10) as i32);
}

/* mandelbrot — the equivalent-semantics C peer for the tuonelang mandelbrot
 * workload (the Benchmarks Game's mandelbrot): the N x N bitmap of the
 * Mandelbrot set over [-1.5, 0.5] x [-1, 1], 50 iterations per point, packed
 * eight pixels to a byte. Instead of writing the PBM to stdout, every packed
 * byte is folded into a checksum (sum = (sum * 31 + byte) % 1000003) so the
 * exit byte witnesses the whole image: sum % 256. -ffp-contract=off keeps
 * 2*Zr*Zi + Ci unfused, as in the other peers. */
#define N 1600

int main(void) {
    long long sum = 0;
    for (long long y = 0; y < N; y++) {
        double ci = 2.0 * (double)y / (double)N - 1.0;
        long long bits = 0, count = 0;
        for (long long x = 0; x < N; x++) {
            double cr = 2.0 * (double)x / (double)N - 1.5;
            double zr = 0.0, zi = 0.0, tr = 0.0, ti = 0.0;
            long long i = 0;
            while (i < 50 && tr + ti <= 4.0) {
                zi = 2.0 * zr * zi + ci;
                zr = tr - ti + cr;
                tr = zr * zr;
                ti = zi * zi;
                i = i + 1;
            }
            bits = bits * 2 + (tr + ti <= 4.0 ? 1 : 0);
            count = count + 1;
            if (count == 8) {
                sum = (sum * 31 + bits) % 1000003;
                bits = 0;
                count = 0;
            }
        }
        if (count > 0) {
            while (count < 8) { bits = bits * 2; count = count + 1; }
            sum = (sum * 31 + bits) % 1000003;
        }
    }
    return (int)(sum % 256);
}

// mandelbrot — the equivalent-semantics Go peer for the tuonelang mandelbrot
// workload (the Benchmarks Game's mandelbrot): the 1600 x 1600 bitmap, 50
// iterations per point, packed eight pixels to a byte, each byte folded into
// sum = (sum * 31 + byte) % 1000003. The 2*Zr*Zi product is wrapped in
// float64 so Go cannot fuse it with "+ Ci" (a fused update flips pixels on
// the set's boundary). Exit byte: sum % 256.
package main

import "os"

const n = 1600

func main() {
	var sum int64
	for y := 0; y < n; y++ {
		ci := 2.0*float64(y)/float64(n) - 1.0
		var bits, count int64
		for x := 0; x < n; x++ {
			cr := 2.0*float64(x)/float64(n) - 1.5
			zr, zi, tr, ti := 0.0, 0.0, 0.0, 0.0
			for i := 0; i < 50 && tr+ti <= 4.0; i++ {
				zi = float64(2.0*zr*zi) + ci
				zr = tr - ti + cr
				tr = zr * zr
				ti = zi * zi
			}
			bit := int64(0)
			if tr+ti <= 4.0 {
				bit = 1
			}
			bits = bits*2 + bit
			count++
			if count == 8 {
				sum = (sum*31 + bits) % 1000003
				bits, count = 0, 0
			}
		}
		if count > 0 {
			for count < 8 {
				bits *= 2
				count++
			}
			sum = (sum*31 + bits) % 1000003
		}
	}
	os.Exit(int(sum % 256))
}

//! mandelbrot — the equivalent-semantics Rust peer for the tuonelang
//! mandelbrot workload (the Benchmarks Game's mandelbrot): the 1600 x 1600
//! bitmap, 50 iterations per point, packed eight pixels to a byte, each byte
//! folded into sum = (sum * 31 + byte) % 1000003. Exit byte: sum % 256.

const N: i64 = 1600;

fn main() {
    let mut sum: i64 = 0;
    for y in 0..N {
        let ci = 2.0 * y as f64 / N as f64 - 1.0;
        let (mut bits, mut count) = (0i64, 0i64);
        for x in 0..N {
            let cr = 2.0 * x as f64 / N as f64 - 1.5;
            let (mut zr, mut zi, mut tr, mut ti) = (0.0f64, 0.0f64, 0.0f64, 0.0f64);
            let mut i = 0;
            while i < 50 && tr + ti <= 4.0 {
                zi = 2.0 * zr * zi + ci;
                zr = tr - ti + cr;
                tr = zr * zr;
                ti = zi * zi;
                i += 1;
            }
            bits = bits * 2 + if tr + ti <= 4.0 { 1 } else { 0 };
            count += 1;
            if count == 8 {
                sum = (sum * 31 + bits) % 1000003;
                bits = 0;
                count = 0;
            }
        }
        if count > 0 {
            while count < 8 {
                bits *= 2;
                count += 1;
            }
            sum = (sum * 31 + bits) % 1000003;
        }
    }
    std::process::exit((sum % 256) as i32);
}

/* fasta — the equivalent-semantics C peer for the tuonelang fasta workload
 * (the Benchmarks Game's fasta): generate the three DNA sequences — ALU
 * repeated for 2N bases, then 3N bases drawn from the IUB code table and 5N
 * from Homo sapiens frequencies, with the benchmark's linear congruential
 * generator — wrapped at 60 bases per line. Instead of writing to stdout,
 * every generated byte (newlines included) is folded into a checksum
 * (sum = (sum * 31 + byte) % 1000003); the exit byte is sum % 256. */
#define N 1000000
#define LINE 60
#define IM 139968
#define IA 3877
#define IC 29573

static const char ALU[] =
    "GGCCGGGCGCGGTGGCTCACGCCTGTAATCCCAGCACTTTGG"
    "GAGGCCGAGGCGGGCGGATCACCTGAGGTCAGGAGTTCGAGA"
    "CCAGCCTGGCCAACATGGTGAAACCCCGTCTCTACTAAAAAT"
    "ACAAAAATTAGCCGGGCGTGGTGGCGCGCGCCTGTAATCCCA"
    "GCTACTCGGGAGGCTGAGGCAGGAGAATCGCTTGAACCCGGG"
    "AGGCGGAGGTTGCAGTGAGCCGAGATCGCGCCACTGCACTCC"
    "AGCCTGGGCGACAGAGCGAGACTCCGTCTCAAAAA";

static long long sum = 0;
static long long last = 42;

static void emit(long long byte) { sum = (sum * 31 + byte) % 1000003; }

static double random_unit(void) {
    last = (last * IA + IC) % IM;
    return (double)last / (double)IM;
}

static void repeat(long long n) {
    long long len = (long long)(sizeof ALU - 1), at = 0, col = 0;
    for (long long i = 0; i < n; i++) {
        emit(ALU[at]);
        at = at + 1;
        if (at == len) at = 0;
        col = col + 1;
        if (col == LINE) { emit('\n'); col = 0; }
    }
    if (col > 0) emit('\n');
}

static void random_seq(const char *codes, const double *cumulative, int count, long long n) {
    long long col = 0;
    for (long long i = 0; i < n; i++) {
        double r = random_unit();
        int k = 0;
        while (k < count - 1 && r >= cumulative[k]) k = k + 1;
        emit(codes[k]);
        col = col + 1;
        if (col == LINE) { emit('\n'); col = 0; }
    }
    if (col > 0) emit('\n');
}

static void cumulate(const double *p, double *out, int count) {
    double acc = 0.0;
    for (int i = 0; i < count; i++) { acc = acc + p[i]; out[i] = acc; }
}

int main(void) {
    static const char iub_codes[] = "acgtBDHKMNRSVWY";
    static const double iub_p[15] = {0.27, 0.12, 0.12, 0.27, 0.02, 0.02, 0.02, 0.02,
                                     0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02};
    static const char homo_codes[] = "acgt";
    static const double homo_p[4] = {0.3029549426680, 0.1979883004921,
                                     0.1975473066391, 0.3015094502008};
    double iub_c[15], homo_c[4];
    cumulate(iub_p, iub_c, 15);
    cumulate(homo_p, homo_c, 4);
    repeat(2 * N);
    random_seq(iub_codes, iub_c, 15, 3 * N);
    random_seq(homo_codes, homo_c, 4, 5 * N);
    return (int)(sum % 256);
}

// fasta — the equivalent-semantics Go peer for the tuonelang fasta workload
// (the Benchmarks Game's fasta): the same three generated sequences, the same
// linear congruential generator, 60 bases per line, every byte folded into
// sum = (sum * 31 + byte) % 1000003. Exit byte: sum % 256.
package main

import "os"

const n = 1000000
const line = 60
const alu = "GGCCGGGCGCGGTGGCTCACGCCTGTAATCCCAGCACTTTGGGAGGCCGAGGCGGGCGGATCACCTGAGGTCAGGAGTTCGAGACCAGCCTGGCCAACATGGTGAAACCCCGTCTCTACTAAAAATACAAAAATTAGCCGGGCGTGGTGGCGCGCGCCTGTAATCCCAGCTACTCGGGAGGCTGAGGCAGGAGAATCGCTTGAACCCGGGAGGCGGAGGTTGCAGTGAGCCGAGATCGCGCCACTGCACTCCAGCCTGGGCGACAGAGCGAGACTCCGTCTCAAAAA"

var sum int64
var last int64 = 42

func emit(b int64) { sum = (sum*31 + b) % 1000003 }

func randomUnit() float64 {
	last = (last*3877 + 29573) % 139968
	return float64(last) / 139968.0
}

func repeat(count int) {
	at, col := 0, 0
	for i := 0; i < count; i++ {
		emit(int64(alu[at]))
		at++
		if at == len(alu) {
			at = 0
		}
		col++
		if col == line {
			emit(10)
			col = 0
		}
	}
	if col > 0 {
		emit(10)
	}
}

func randomSeq(codes string, cumulative []float64, count int) {
	col := 0
	for i := 0; i < count; i++ {
		r := randomUnit()
		k := 0
		for k < len(cumulative)-1 && r >= cumulative[k] {
			k++
		}
		emit(int64(codes[k]))
		col++
		if col == line {
			emit(10)
			col = 0
		}
	}
	if col > 0 {
		emit(10)
	}
}

func cumulate(p []float64) []float64 {
	out := make([]float64, len(p))
	acc := 0.0
	for i, x := range p {
		acc = acc + x
		out[i] = acc
	}
	return out
}

func main() {
	iub := cumulate([]float64{0.27, 0.12, 0.12, 0.27, 0.02, 0.02, 0.02, 0.02,
		0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02})
	homo := cumulate([]float64{0.3029549426680, 0.1979883004921, 0.1975473066391, 0.3015094502008})
	repeat(2 * n)
	randomSeq("acgtBDHKMNRSVWY", iub, 3*n)
	randomSeq("acgt", homo, 5*n)
	os.Exit(int(sum % 256))
}

//! fasta — the equivalent-semantics Rust peer for the tuonelang fasta workload
//! (the Benchmarks Game's fasta): the same three generated sequences, the same
//! linear congruential generator, 60 bases per line, every byte folded into
//! sum = (sum * 31 + byte) % 1000003. Exit byte: sum % 256.

const N: i64 = 1_000_000;
const LINE: i64 = 60;
const ALU: &[u8] = b"GGCCGGGCGCGGTGGCTCACGCCTGTAATCCCAGCACTTTGGGAGGCCGAGGCGGGCGGATCACCTGAGGTCAGGAGTTCGAGACCAGCCTGGCCAACATGGTGAAACCCCGTCTCTACTAAAAATACAAAAATTAGCCGGGCGTGGTGGCGCGCGCCTGTAATCCCAGCTACTCGGGAGGCTGAGGCAGGAGAATCGCTTGAACCCGGGAGGCGGAGGTTGCAGTGAGCCGAGATCGCGCCACTGCACTCCAGCCTGGGCGACAGAGCGAGACTCCGTCTCAAAAA";

struct Gen {
    sum: i64,
    last: i64,
}

impl Gen {
    fn emit(&mut self, byte: i64) {
        self.sum = (self.sum * 31 + byte) % 1000003;
    }

    fn random_unit(&mut self) -> f64 {
        self.last = (self.last * 3877 + 29573) % 139968;
        self.last as f64 / 139968.0
    }

    fn repeat(&mut self, n: i64) {
        let (mut at, mut col) = (0usize, 0i64);
        for _ in 0..n {
            self.emit(ALU[at] as i64);
            at += 1;
            if at == ALU.len() {
                at = 0;
            }
            col += 1;
            if col == LINE {
                self.emit(10);
                col = 0;
            }
        }
        if col > 0 {
            self.emit(10);
        }
    }

    fn random_seq(&mut self, codes: &[u8], cumulative: &[f64], n: i64) {
        let mut col = 0;
        for _ in 0..n {
            let r = self.random_unit();
            let mut k = 0;
            while k < cumulative.len() - 1 && r >= cumulative[k] {
                k += 1;
            }
            self.emit(codes[k] as i64);
            col += 1;
            if col == LINE {
                self.emit(10);
                col = 0;
            }
        }
        if col > 0 {
            self.emit(10);
        }
    }
}

fn cumulate(p: &[f64]) -> Vec<f64> {
    let mut acc = 0.0;
    p.iter()
        .map(|x| {
            acc = acc + x;
            acc
        })
        .collect()
}

fn main() {
    let iub = cumulate(&[
        0.27, 0.12, 0.12, 0.27, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02,
    ]);
    let homo = cumulate(&[0.3029549426680, 0.1979883004921, 0.1975473066391, 0.3015094502008]);
    let mut g = Gen { sum: 0, last: 42 };
    g.repeat(2 * N);
    g.random_seq(b"acgtBDHKMNRSVWY", &iub, 3 * N);
    g.random_seq(b"acgt", &homo, 5 * N);
    std::process::exit((g.sum % 256) as i32);
}
